const slug = value => value.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function card(name,section,region,location,action,origin,insertion,figures=[],extra={}) {
  return {
    id:`ch11-${slug(name)}`,name,section,region,kind:'muscle',location,action,origin,insertion,
    figures,aliases:[],courseChecklist:true,
    guidePrompt:`Ask me to locate ${name}, explain a main action, and connect its general attachments to that action. Ask one question at a time.`,
    sourceNotes:'General attachment regions for study; verify the selected specimen and view before identifying a precise surface.',
    ...extra,
    sourceClass:extra.courseChecklist===false?'chapter-reference':'course-checklist',
    attachmentScope:'general-regions'
  };
}
const extra={courseChecklist:false};

